// === Tab: mySketch ===
// Create a Particle System using custom Javascript Objects (ES6 class notation). 
// Your Particle object must contain the following properties: position, size, color, speed.

// Inspired by Vincent van Gogh's The Starry Night

// set variable for noise, larger number has better results to move across the screen
var noiseScale = 500;
// set variable if particles are following (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) and (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))
var isFollowing = false; 
// set variable for total number of particles
var total = 0;

// particle colors
var colors = [
	{r: 55, g: 202, b: 229}, // blue
	{r: 252, g: 202, b: 70}, // yellow
	{r: 251, g: 239, b: 203} // off white
]

class Particle {
	constructor(position, color, speed) {
		this.position = position;
		this.color = color;
		this.speed = speed;
		this.size = 15;
		this.alpha = 0; // set alpha to 0 to create ease in for new particles
		this.direction = createVector(0, 0);
		this.lifespan = Math.floor(random(100, 255)); // use random so that particles 'die' at different times
	}

	move() {
		// increase alpha as particle moves
		this.alpha ++ 

		// decrease lifespan as particle moves
		if (this.lifespan > 0) {
			this.lifespan--
		}

		// if particles are following (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) and (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))
		if (isFollowing) {
			// assign (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) and (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) as target
			var target = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
			// calculate the distance between target and current position
			var distance = target.dist(this.position);
			// map the distance between positions to speed and 0
			var mappedDistance = map(distance, 100, 0, this.speed, 0);
			// calculate the direction of your target towards position
			target = createVector(target.x - this.position.x, target.y - this.position.y);
			// normalize sets the length of the vector to 1
			target.normalize();
			// add the target vector to position
			this.position = createVector(this.position.x + target.x * mappedDistance, this.position.y + target.y * mappedDistance)
		} else {
			// create angles with noiseScale
			this.angle = noise(this.position.x / noiseScale, this.position.y / noiseScale) * TWO_PI;
			// use cos and sin curves to mimic shapes of the swirls in van Gogh's painting
			this.direction.x = -cos(this.angle);
			this.direction.y = sin(this.angle);
			// add the direction to the current position of the particle
			this.position = createVector(this.position.x + this.direction.x * this.speed, this.position.y + this.direction.y * this.speed)
		}
	}
}

var particles = []
var particle

function setup() {
	noStroke();
	createCanvas(windowWidth, windowHeight);
	// using width and height to determine number of particles we want on screen
	total = windowWidth / 25 * windowHeight / 25

	// create and store particles in an array
	for (var i = 0; i < total; i++) {
		particles.push(new Particle(createVector(random(width), random(height)), colors[Math.floor(random(3))], random(0.5, 1)));
	}
}

function draw() {
	// instead of a background fill
	// use a filled rectangle with alpha value in order to create disappearing "tail" 
	fill(18, 63, 119, 10)
	rect(0, 0, width, height)

	for (var i = 0; i < particles.length; i++) {
		// destructure data, position & color of each particle
		const {position, size, color, alpha} = particles[i]
		const {r, g, b} = color
		const {x, y} = position

		// fill each ellipse with rgb value and alpha value
		fill(r, g, b, alpha)
		ellipse(x, y, size);

		// call move function
		particles[i].move()

		// if particles have reached the end of their lifespan
		// or are at the edges of the window,
		// remove them from the array and create a replacement partcile
		if (particles[i].lifespan === 0 || x < 0 || x > width || y > height || y < 0) {
			particles.splice(i, 1)
			particles.push(new Particle(createVector(random(width), random(height)), colors[Math.floor(random(3))], random(0.5, 1)));
		}
	}
}

// if mousepressed, set the particles to follow/!follow (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) and (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))
function mousePressed() {
	isFollowing = !isFollowing
}

